'use strict';
const WS={prefs:{settings:{currency:'USD',capital:0,name:'My trading journal'},revision:0},guard:{settings:{enabled:false,riskPerTrade:.5,dailyLoss:2,maxDrawdown:10,maxTrades:3,maxOpenRisk:2,requireRoutine:false,requireChecklist:false},revision:0},items:{note:[],strategy:[],event:[],session:[],resource:[],blocked:[]},errors:[],filters:{from:'',to:'',symbol:'',direction:'',review:''},page:1,dialogDirty:false,dialogBusy:false,dayDrafts:{},focus:null,focusTimer:null};
const wsJson=(value,fallback={})=>{try{return typeof value==='string'?JSON.parse(value):value||fallback;}catch{return fallback;}};
const wsClosed=t=>t.pnl!==null&&t.pnl!==''&&t.pnl!==undefined&&Number.isFinite(Number(t.pnl));
const wsNet=t=>(Number(t.pnl)||0)-(Number(t.fee)||0);
const wsReview=t=>wsJson(t.review);
const wsReviewed=t=>wsReview(t).reviewed===true;
const wsSign=value=>value>0?'pos':value<0?'neg':'muted';
const wsNum=(value,digits=2)=>Number.isFinite(value)?Number(value).toLocaleString(undefined,{maximumFractionDigits:digits}):'—';
const wsDate=value=>value?new Date(value).toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'}):'—';
const wsLocalDate=()=>{const now=new Date();return `${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-${String(now.getDate()).padStart(2,'0')}`;};
// Amounts are stored in the journal's base currency; the display currency converts them at the saved rate.
const wsDisplayCurrency=()=>WS.prefs.settings.displayCurrency||WS.prefs.settings.currency;
const wsFx=()=>{const p=WS.prefs.settings;return wsDisplayCurrency()===p.currency?1:(Number(p.fxRate)||1);};
window.workspaceMoney=value=>{if(value===null||value===''||value===undefined||!Number.isFinite(Number(value)))return '—';const currency=wsDisplayCurrency(),amount=Number(value)*wsFx();if(currency==='USDT')return `${amount<0?'-':''}${Math.abs(amount).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2})} USDT`;return new Intl.NumberFormat(undefined,{style:'currency',currency,currencyDisplay:'narrowSymbol',minimumFractionDigits:2,maximumFractionDigits:2}).format(amount);};
async function wsApi(path,method='GET',body){const response=await fetch('/api/workspace/'+path,{method,headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});const result=await response.json();if(!response.ok)throw Error(result.error||'Request failed');return result;}
async function loadWorkspace(){const jobs=[['prefs',()=>wsApi('preferences')],['guard',()=>wsApi('guardrails')],...Object.keys(WS.items).map(kind=>[kind,()=>wsApi('items?kind='+kind)])];const results=await Promise.allSettled(jobs.map(([,fn])=>fn()));WS.errors=[];results.forEach((result,i)=>{const key=jobs[i][0];if(result.status==='fulfilled'){if(key in WS.items)WS.items[key]=result.value;else WS[key]=result.value;}else WS.errors.push(key);});return WS.errors.length===0;}
async function wsReload(kind){WS.items[kind]=await wsApi('items?kind='+kind);}
function wsErrorBanner(){return WS.errors.length?`<div class="ws-notice warning">Some journal sections could not load (${esc(WS.errors.join(', '))}). <button class="ws-link" data-ws-action="reload">Retry loading</button></div>`:'';}
const wsBtn=(label,action,ghost=false,extra='')=>`<button type="button" class="btn${ghost?' ghost':''}" data-ws-action="${action}" ${extra}>${label}</button>`;
const wsEmpty=(title,copy,action,label)=>`<div class="ws-empty"><span class="ws-empty-icon" aria-hidden="true">◇</span><b>${title}</b><p>${copy}</p>${action?wsBtn(label,action):''}</div>`;
const wsHeader=(eyebrow,title,copy,actions='')=>`<div class="ws-head"><div><div class="ws-eyebrow">${eyebrow}</div><h1>${title}</h1><p class="ws-subtitle">${copy}</p></div><div class="ws-actions">${actions}</div></div>${wsErrorBanner()}`;
const wsKpi=(label,value,copy,sign='')=>`<div class="ws-card ws-kpi"><div class="ws-label"><span class="ws-trend-dot"></span>${label}</div><div class="ws-value ${sign}">${value}</div><div class="ws-foot">${copy}</div></div>`;
function wsFiltered(){const f=WS.filters;return allTrades.filter(t=>(!f.from||t.date>=f.from)&&(!f.to||t.date<=f.to)&&(!f.symbol||[t.symbol,t.setup,t.notes,t.tags].some(v=>String(v||'').toLowerCase().includes(f.symbol.toLowerCase())))&&(!f.direction||t.direction===f.direction)&&(!f.review||(f.review==='open'?!wsClosed(t):f.review==='reviewed'?wsReviewed(t):wsClosed(t)&&!wsReviewed(t))));}
function wsSummary(trades=allTrades){const closed=trades.filter(wsClosed).sort((a,b)=>(a.date||'').localeCompare(b.date||'')||a.id-b.id);const nets=closed.map(wsNet),wins=nets.filter(v=>v>0),losses=nets.filter(v=>v<0);let running=0,peak=0,maxDD=0,maxDDPct=0;const capital=Number(WS.prefs.settings.capital)||0;const equity=[{date:'Start',value:0}];closed.forEach(t=>{running+=wsNet(t);peak=Math.max(peak,running);maxDD=Math.max(maxDD,peak-running);if(capital+peak>0)maxDDPct=Math.max(maxDDPct,(peak-running)/(capital+peak)*100);equity.push({date:t.date,value:running});});const reviews=closed.filter(wsReviewed),planReviews=reviews.filter(t=>[true,false].includes(wsReview(t).followedPlan)),followed=planReviews.filter(t=>wsReview(t).followedPlan===true);const rs=closed.map(t=>t.r_multiple).filter(v=>v!==null&&v!==''&&Number.isFinite(Number(v))).map(Number);return{closed,net:nets.reduce((a,b)=>a+b,0),gross:closed.reduce((a,t)=>a+(Number(t.pnl)||0),0),fees:closed.reduce((a,t)=>a+(Number(t.fee)||0),0),wins:wins.length,losses:losses.length,winRate:closed.length?wins.length/closed.length*100:0,pf:losses.length?wins.reduce((a,b)=>a+b,0)/Math.abs(losses.reduce((a,b)=>a+b,0)):(wins.length?Infinity:0),avgWin:wins.length?wins.reduce((a,b)=>a+b,0)/wins.length:0,avgLoss:losses.length?losses.reduce((a,b)=>a+b,0)/losses.length:0,drawdown:peak-running,drawdownPct:capital+peak>0?(peak-running)/(capital+peak)*100:0,avgR:rs.length?rs.reduce((a,b)=>a+b,0)/rs.length:0,expectancy:closed.length?running/closed.length:0,maxDD,maxDDPct,equity,reviews:reviews.length,planReviews:planReviews.length,compliance:planReviews.length?followed.length/planReviews.length*100:null,open:trades.filter(t=>!wsClosed(t)),pending:closed.filter(t=>!wsReviewed(t))};}
function wsFilters(){const f=WS.filters;return `<form class="ws-filter" id="wsFilterForm"><label class="ws-field">From<input type="date" name="from" value="${esc(f.from)}"></label><label class="ws-field">To<input type="date" name="to" value="${esc(f.to)}"></label><label class="ws-field ws-search">Search<input name="symbol" value="${esc(f.symbol)}" placeholder="Symbol, setup, notes or tag"></label><label class="ws-field">Direction<select name="direction"><option value="">All directions</option>${['Long','Short'].map(v=>`<option ${f.direction===v?'selected':''}>${v}</option>`).join('')}</select></label><label class="ws-field">Review status<select name="review"><option value="">All trades</option>${[['pending','Needs review'],['reviewed','Reviewed'],['open','Open']].map(([value,label])=>`<option value="${value}" ${f.review===value?'selected':''}>${label}</option>`).join('')}</select></label><button class="btn" type="submit">Apply</button>${wsBtn('Clear','clear-filters',true)}</form>`;}
function wsWireFilters(){const form=$('#wsFilterForm');if(form)form.onsubmit=event=>{event.preventDefault();const data=Object.fromEntries(new FormData(form));if(data.from&&data.to&&data.from>data.to){toast('From date must be before To date');return;}WS.filters=data;WS.page=1;renderWorkspaceView(view);};}
function wsTradeTable(trades,compact=false){if(!trades.length)return wsEmpty('Your next insight starts with a trade','Log a trade manually or import your completed trades to start building your journal.','new-trade','+ Add trade');return `<div class="ws-table-wrap"><table class="ws-table ${compact?'ws-table-compact':''}"><thead><tr><th>Instrument</th><th>Date</th>${compact?'':'<th>Direction</th><th>Plan / setup</th><th class="right">Return (R)</th>'}<th class="right">Net P&L</th><th>Review</th><th></th></tr></thead><tbody>${trades.map(t=>`<tr data-ws-trade="${t.id}" tabindex="0" aria-label="Review ${esc(t.symbol)} trade"><td><b>${esc(t.symbol||'Untitled')}</b>${compact?`<span class="sub">${esc(t.direction||'')}</span>`:''}</td><td class="num muted">${esc(t.date||'—')}</td>${compact?'':`<td><span class="ws-tag ${t.direction==='Long'?'green':'red'}">${esc(t.direction||'—')}</span></td><td>${esc(wsJson(t.plan).template?.name||t.setup||'—')}</td><td class="right num">${t.r_multiple==null?'—':fmt(t.r_multiple)+'R'}</td>`}<td class="right num ${wsClosed(t)?wsSign(wsNet(t)):''}">${wsClosed(t)?money(wsNet(t)):'Open'}</td><td><span class="ws-tag ${wsReviewed(t)?'green':wsClosed(t)?'amber':'purple'}">${wsReviewed(t)?'Reviewed':wsClosed(t)?'To review':'Open'}</span></td><td><button type="button" class="ws-link" data-ws-action="trade-detail" data-id="${t.id}" aria-label="Review ${esc(t.symbol)}">↗</button></td></tr>`).join('')}</tbody></table></div>`;}
function wsInsights(summary){const result=[];if(!summary.closed.length)return wsEmpty('Insights from your own trades','Once you log completed trades, this section will show review gaps, plan adherence and performance patterns.');if(summary.pending.length)result.push(['↗',`${summary.pending.length} trade${summary.pending.length===1?'':'s'} waiting for review`,'Record the setup quality, emotions and lessons while the details are fresh.']);if(summary.compliance!==null)result.push(['◎',`${wsNum(summary.compliance,0)}% plan adherence`,`${summary.planReviews} reviewed trades with a Yes/No answer. This uses your plan-following answers.`]);const groups=wsGroups(summary.closed,t=>t.setup||'Unassigned');if(groups.length>1)result.push(['↗',`${groups[0].name} has the highest recorded net P&L`,`${groups[0].n} completed trades · ${money(groups[0].net)} after fees. This describes the sample you logged.`]);if(summary.fees>0)result.push(['≋',`${money(summary.fees)} in recorded fees`,'Net P&L, win rate and the equity curve include those costs.']);if(summary.maxDD>0)result.push(['↓',`${money(summary.maxDD)} maximum drawdown`,'Largest recorded fall from a previous equity peak.']);if(!result.length)result.push(['✓','Your reviews are up to date','Keep logging the context and execution behind each result.']);return result.map(([icon,title,copy])=>`<div class="ws-insight"><span class="ws-insight-icon" aria-hidden="true">${icon}</span><div><b>${esc(title)}</b><p>${esc(copy)}</p></div></div>`).join('');}
function wsGroups(trades,getKey){const map=new Map();trades.filter(wsClosed).forEach(t=>{const name=getKey(t)||'Not recorded';const group=map.get(name)||{name,n:0,net:0,wins:0};group.n++;group.net+=wsNet(t);if(wsNet(t)>0)group.wins++;map.set(name,group);});return [...map.values()].sort((a,b)=>b.net-a.net);}
function wsGroupTable(groups){return groups.length?`<div class="ws-table-wrap"><table class="ws-table ws-table-compact"><thead><tr><th>Group</th><th>Trades</th><th>Win rate</th><th class="right">Net P&L</th></tr></thead><tbody>${groups.map(g=>`<tr><td>${esc(g.name)}</td><td>${g.n}</td><td>${wsNum(g.wins/g.n*100,1)}%</td><td class="right num ${wsSign(g.net)}">${money(g.net)}</td></tr>`).join('')}</tbody></table></div>`:wsEmpty('No completed trades','This breakdown will use the trades and review details you record.');}
function wsDrawEquity(id,summary){const canvas=$('#'+id);if(!canvas)return;const width=Math.max(240,canvas.clientWidth),height=240,dpr=devicePixelRatio||1;canvas.width=width*dpr;canvas.height=height*dpr;const ctx=canvas.getContext('2d');ctx.scale(dpr,dpr);const css=getComputedStyle(document.documentElement),mut=css.getPropertyValue('--mut'),line=css.getPropertyValue('--line'),accent=css.getPropertyValue('--accent');ctx.font='10px -apple-system,sans-serif';if(!summary.closed.length){ctx.fillStyle=mut;ctx.textAlign='center';ctx.fillText('Your equity curve will appear after your first closed trade.',width/2,height/2);canvas.setAttribute('aria-label','No completed trades for equity curve');return;}const points=summary.equity,values=points.map(p=>p.value);let min=Math.min(...values),max=Math.max(...values),span=max-min||1;const left=66,right=12,top=16,bottom=25;min-=span*.08;max+=span*.08;span=max-min;const px=i=>left+i*(width-left-right)/(points.length-1||1),py=v=>top+(max-v)/span*(height-top-bottom);ctx.textAlign='right';for(let i=0;i<4;i++){const value=min+span*i/3,y=py(value);ctx.strokeStyle=line;ctx.beginPath();ctx.moveTo(left,y);ctx.lineTo(width-right,y);ctx.stroke();ctx.fillStyle=mut;ctx.fillText(wsNum(value*wsFx(),0),left-9,y+3);}ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(px(i),py(p.value)):ctx.moveTo(px(i),py(p.value)));ctx.lineWidth=2;ctx.strokeStyle=accent;ctx.stroke();ctx.lineTo(px(points.length-1),height-bottom);ctx.lineTo(left,height-bottom);ctx.closePath();const gradient=ctx.createLinearGradient(0,top,0,height-bottom);gradient.addColorStop(0,accent.trim()+'22');gradient.addColorStop(1,accent.trim()+'00');ctx.fillStyle=gradient;ctx.fill();ctx.fillStyle=accent;ctx.beginPath();ctx.arc(px(points.length-1),py(points.at(-1).value),3,0,7);ctx.fill();canvas.setAttribute('aria-label',`Cumulative net P&L: ${money(summary.net)} across ${summary.closed.length} closed trades. Maximum drawdown ${money(summary.maxDD)}.`);canvas.onmousemove=event=>{const rect=canvas.getBoundingClientRect(),i=Math.max(0,Math.min(points.length-1,Math.round((event.clientX-rect.left-left)/(width-left-right)*(points.length-1))));canvas.title=`${points[i].date}: ${money(points[i].value)}`;};}
function renderDashboard(){const s=wsSummary(),today=wsLocalDate(),day=allTrades.filter(t=>t.date===today),daySummary=wsSummary(day),capital=WS.prefs.settings.capital;const routine=routineState,done=routine?routine.checked.length:0,total=routine?routine.settings.steps.length:0;const events=WS.items.event.filter(e=>Date.parse(e.body.at)>=Date.now()).sort((a,b)=>Date.parse(a.body.at)-Date.parse(b.body.at)).slice(0,3);$('#ws-dashboard').innerHTML=wsHeader('ANALYTICS · OVERVIEW','A clearer view of your trading.','Prepare with intent. Trade from a plan. Learn from every session.',`<span class="ws-date">${esc(new Date().toLocaleDateString(undefined,{weekday:'long',month:'short',day:'numeric'}))}</span>${wsBtn('+ Add trade','new-trade')}`)+`<div class="ws-kpis">${wsKpi('Net P&L',money(s.net),`${s.closed.length} closed trades · after fees`,wsSign(s.net))}${wsKpi('Win rate',s.closed.length?wsNum(s.winRate,1)+'%':'—',`${s.wins} wins · ${s.losses} losses`)}${wsKpi('Profit factor',s.closed.length?(Number.isFinite(s.pf)?wsNum(s.pf):'∞'):'—','Net profits ÷ absolute net losses')}${wsKpi('Plan adherence',s.compliance===null?'—':wsNum(s.compliance,0)+'%',`${s.reviews} trades reviewed`)}</div>
<div class="ws-grid"><section class="ws-card ws-span-8"><div class="ws-card-head"><h2>Equity curve</h2><span class="ws-tag purple">${esc(wsDisplayCurrency())} · net of fees</span></div><canvas class="ws-chart" id="wsDashboardEquity" role="img"></canvas><div class="ws-chart-foot"><span>${esc(s.closed[0]?.date||'Your first trade')}</span><span>${esc(s.closed.at(-1)?.date||'Today')}</span></div></section>
<section class="ws-card ws-span-4"><div class="ws-card-head"><h2>Your trading day</h2><span class="ws-tag">${day.length} trades today</span></div><div class="ws-discipline"><div class="ws-ring" style="--progress:${total?done/total*100:0}%"><span>${done}/${total}</span></div><div><b>Pre-market routine</b><p class="ws-subtitle">Small actions. Consistent process.</p><button class="ws-link" data-ws-action="routine">Open checklist →</button></div></div><hr class="ws-divider"><div class="ws-progress-row"><div>Today’s net P&L<span class="sub">Closed trades after fees</span></div><b class="num ${wsSign(daySummary.net)}">${money(daySummary.net)}</b></div><div class="ws-progress-row"><div>Open positions<span class="sub">Recorded without realized P&L</span></div><b>${s.open.length}</b></div><div class="ws-progress-row"><div>Journal balance<span class="sub">Starting balance + recorded net P&L</span></div><b>${capital>0?money(capital+s.net):'<button class="ws-link" data-ws-action="preferences">Set balance →</button>'}</b></div></section>
<section class="ws-card ws-span-8"><div class="ws-card-head"><h2>Recent trades</h2><button class="ws-link" data-ws-action="trades">View all trades →</button></div>${wsTradeTable(allTrades.slice(0,5),true)}</section>
<section class="ws-card ws-span-4"><div class="ws-card-head"><h2>Next best action</h2><span class="ws-tag purple">Your process</span></div><ul class="ws-list"><li><span class="ws-check-dot">1</span><div>${done<total?'Finish your preparation':'Your preparation is complete'}<span class="sub">${done} of ${total} routine steps complete</span></div></li><li><span class="ws-check-dot">2</span><div>Review your trade plan<span class="sub">Keep entry, risk and invalidation clear.</span><button class="ws-link" data-ws-action="strategies">Open your plans →</button></div></li><li><span class="ws-check-dot">3</span><div>${s.pending.length?'Reflect on '+s.pending.length+' completed trades':'Keep your journal current'}<span class="sub">Capture the decision behind each result.</span><button class="ws-link" data-ws-action="pending">${s.pending.length?'Review trades':'Open journal'} →</button></div></li></ul></section>
<section class="ws-card ws-span-7"><div class="ws-card-head"><h2>Journal insights</h2><span class="ws-tag">Calculated from your records</span></div>${wsInsights(s)}</section><section class="ws-card ws-span-5"><div class="ws-card-head"><h2>On your calendar</h2><button class="ws-link" data-ws-action="events">View calendar →</button></div>${events.length?events.map(wsEventRow).join(''):wsEmpty('Prepare for the next session','Add the events that matter to the markets you trade. Events are entered manually.','new-event','+ Add event')}</section></div>`;wsDrawEquity('wsDashboardEquity',s);}
function renderTradeHistory(){const list=wsFiltered(),max=Math.max(1,Math.ceil(list.length/20));WS.page=Math.max(1,Math.min(WS.page,max));$('#ws-trades').innerHTML=wsHeader('ALL TRADES','Trades','Every trade, its context, and what you learned.',`${wsBtn('Import CSV','import',true)}${wsBtn('Export CSV','export',true)}${wsBtn('+ Add trade','new-trade')}`)+wsFilters()+wsTradeTable(list.slice((WS.page-1)*20,WS.page*20))+`<div class="ws-pager"><span>${list.length} matching trades · click a row to review</span><div class="ws-actions">${wsBtn('← Previous','prev-page',true,WS.page<=1?'disabled':'')}<span>Page ${WS.page} of ${max}</span>${wsBtn('Next →','next-page',true,WS.page>=max?'disabled':'')}</div></div>`;wsWireFilters();}
function renderPerformanceWorkspace(){const trades=wsFiltered(),s=wsSummary(trades);$('#ws-performance').innerHTML=wsHeader('YOUR NUMBERS','Stats','Measure the result and the process. All figures use the selected trades.',`${wsBtn('Export selected trades','export',true)}`)+wsFilters()+`<div class="ws-kpis">${wsKpi('Net P&L',money(s.net),`Gross ${money(s.gross)} · fees ${money(s.fees)}`,wsSign(s.net))}${wsKpi('Win rate',s.closed.length?wsNum(s.winRate,1)+'%':'—',`${s.closed.length} completed trades`)}${wsKpi('Expectancy',s.closed.length?money(s.expectancy):'—','Mean net P&L per completed trade',wsSign(s.expectancy))}${wsKpi('Max drawdown',money(s.maxDD),'Largest fall from a previous equity peak')}</div><div class="ws-grid"><section class="ws-card ws-span-8"><div class="ws-card-head"><h2>Cumulative net P&L</h2><span class="ws-tag purple">${esc(wsDisplayCurrency())}</span></div><canvas id="wsPerformanceEquity" class="ws-chart" role="img"></canvas></section><section class="ws-card ws-span-4"><h2>Trading statistics</h2>${[['Average win',money(s.avgWin)],['Average loss',money(s.avgLoss)],['Profit factor',Number.isFinite(s.pf)?wsNum(s.pf):'∞'],['Average recorded R',wsNum(s.avgR)+'R'],['Open trades',s.open.length],['Reviewed trades',s.reviews],['Plan adherence',s.compliance===null?'—':wsNum(s.compliance,0)+'%']].map(([label,value])=>`<div class="ws-progress-row"><span>${label}</span><b class="num">${value}</b></div>`).join('')}</section>${[['By setup',t=>t.setup||wsJson(t.plan).template?.name||'Unassigned'],['By direction',t=>t.direction],['By entry emotion',t=>wsReview(t).emotionIn],['By weekday',t=>new Date(t.date+'T12:00:00').toLocaleDateString(undefined,{weekday:'long'})],['By plan adherence',t=>wsReview(t).followedPlan===true?'Followed plan':wsReview(t).followedPlan===false?'Broke plan':'Not reviewed'],['By setup quality',t=>wsReview(t).quality]].map(([label,key])=>`<section class="ws-card ws-span-6"><div class="ws-card-head"><h2>${label}</h2><span class="ws-tag">Closed trades</span></div>${wsGroupTable(wsGroups(s.closed,key))}</section>`).join('')}<section class="ws-card ws-span-12"><div class="ws-card-head"><h2>What your journal shows</h2><span class="ws-tag">Recorded results · no AI service connected</span></div>${wsInsights(s)}</section></div>`;wsWireFilters();wsDrawEquity('wsPerformanceEquity',s);}
// Replace the old gross-only analytics with the same net metrics throughout the app.
renderAllTable=renderTradeHistory;loadPerformance=async()=>renderPerformanceWorkspace();renderEquity=()=>{if(view==='performance')wsDrawEquity('wsPerformanceEquity',wsSummary(wsFiltered()));if(view==='dashboard')wsDrawEquity('wsDashboardEquity',wsSummary());};
function wsShowDialog(title,copy,body,wide=false){const dialog=$('#wsDialog');if(WS.dialogBusy)return false;if(dialog.open&&WS.dialogDirty&&!confirm('Discard the unsaved edits in this window?'))return false;dialog.classList.toggle('wide',wide);dialog.innerHTML=`<div class="ws-dialog-header"><div><h2 id="wsDialogTitle">${title}</h2>${copy?`<p>${copy}</p>`:''}</div><button type="button" data-ws-action="close-dialog" aria-label="Close">×</button></div><div class="ws-dialog-body">${body}</div>`;WS.dialogDirty=false;WS.dialogBusy=false;dialog.oninput=()=>WS.dialogDirty=true;dialog.oncancel=event=>{if(WS.dialogBusy){event.preventDefault();return;}if(WS.dialogDirty&&!confirm('Discard unsaved changes?'))event.preventDefault();};if(!dialog.open)dialog.showModal();return true;}
function wsCloseDialog(force=false){if(WS.dialogBusy&&!force)return;if(!force&&WS.dialogDirty&&!confirm('Discard unsaved changes?'))return;$('#wsDialog').close();WS.dialogDirty=false;WS.dialogBusy=false;}
function wsField(label,name,value='',type='text',full=false){return `<label class="ws-field${full?' full':''}">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${name==='title'?'required maxlength="200"':''}></label>`;}
function wsTextField(label,name,value='',full=true){return `<label class="ws-field${full?' full':''}">${label}<textarea name="${name}">${esc(value)}</textarea></label>`;}
function wsSelect(label,name,options,current='',full=false){return `<label class="ws-field${full?' full':''}">${label}<select name="${name}">${options.map(option=>{const [key,label]=Array.isArray(option)?option:[option,option];return `<option value="${esc(key)}" ${String(current)===String(key)?'selected':''}>${esc(label)}</option>`;}).join('')}</select></label>`;}
const wsLines=value=>String(value||'').split('\n').map(line=>line.trim()).filter(Boolean);
const wsLocalInput=value=>{const date=value?new Date(value):new Date();return new Date(date.getTime()-date.getTimezoneOffset()*60000).toISOString().slice(0,16);};
function wsOpenItemEditor(kind,item=null){const names={note:'note',strategy:'trade plan',event:'calendar event',resource:'learning resource'},body=item?.body||{},isNew=!item;let itemUploads=0;const seedRefs=kind==='strategy'?(item?.body||PLAN_SETTINGS.templates[PLAN_SETTINGS.defaultType]):{},references={setupImages:clonePlan(seedRefs.setupImages||[]),entryImages:clonePlan(seedRefs.entryImages||[])};let fields=wsField('Title','title',item?.title||'','text',true);if(kind==='note')fields+=wsTextField('Your note','content',body.content||'')+wsField('Tags · comma separated','tags',body.tags||'','text',true)+`<label class="ws-check full"><input type="checkbox" name="pinned" ${body.pinned?'checked':''}>Pin this note</label>`;
if(kind==='strategy'){const seed=item?body:PLAN_SETTINGS.templates[PLAN_SETTINGS.defaultType];fields+=wsTextField('Plan type · e.g. LQ Sweep Entry Model','description',body.description||'')+wsTextField('Charting process · one step per line','charting',(seed.charting||[]).join('\n'))+wsTextField('Entry criteria · one item per line','criteria',(seed.criteria||[]).join('\n'))+wsTextField('Trade management · one rule per line','management',(seed.management||[]).join('\n'))+wsTextField('Exit criteria','exitRules',seed.exitRules||'')+wsTextField('Trading notes · one item per line','notes',(seed.notes||[]).join('\n'))+`<label class="ws-check full"><input type="checkbox" name="active" ${body.active!==false?'checked':''}>Available for new trades (untick to archive)</label>`;}
if(kind==='strategy')fields+=['setupImages','entryImages'].map(key=>`<div class="full"><p class="ws-subtitle">${key==='setupImages'?'Setup reference charts':'Entry example charts'} · up to 8</p><div class="settings-reference" id="wsPlanRefs_${key}"></div><label class="ws-link">+ Upload chart<input type="file" data-plan-reference="${key}" accept="image/png,image/jpeg,image/webp,image/gif" hidden></label></div>`).join('');
if(kind==='event')fields+=wsField('Date and time · your local timezone','at',wsLocalInput(body.at),'datetime-local')+wsSelect('Impact','impact',['low','medium','high'],body.impact||'medium')+wsField('Currency / market','currency',body.currency||'')+wsField('Source link','source',body.source||'','url')+wsTextField('Preparation notes','notes',body.notes||'');
if(kind==='resource')fields+=wsField('Link · optional','url',body.url||'','url',true)+wsField('Category','category',body.category||'Learning','text',true)+wsTextField('Notes and takeaways','notes',body.notes||'');
const copy=kind==='strategy'?'New trades take a snapshot of this plan. Saved trades keep their recorded version.':kind==='event'?'This is a manually added event. Dates display in your local timezone.':'Saved privately in your local journal.';
if(!wsShowDialog(`${isNew?'New':'Edit'} ${names[kind]}`,copy,`<form id="wsItemForm"><div class="ws-form-grid">${fields}</div><div class="ws-form-footer"><span class="ws-form-status" id="wsItemStatus" role="status"></span>${item?wsBtn('Delete','delete-item',true,`data-id="${item.id}" data-kind="${kind}"`):''}${wsBtn('Cancel','close-dialog',true)}<button class="btn" type="submit">Save ${names[kind]}</button></div></form>`))return;
const renderReferences=()=>{for(const key of ['setupImages','entryImages']){const target=$('#wsPlanRefs_'+key);if(!target)continue;target.innerHTML=references[key].map((path,i)=>`<div class="shot"><img src="/${esc(path)}" alt="Plan reference chart ${i+1}"><button type="button" data-remove-plan-ref="${i}" aria-label="Remove chart">×</button></div>`).join('');target.querySelectorAll('[data-remove-plan-ref]').forEach(button=>button.onclick=()=>{if(itemUploads)return;references[key].splice(+button.dataset.removePlanRef,1);WS.dialogDirty=true;renderReferences();});}};
renderReferences();$$('#wsItemForm [data-plan-reference]').forEach(input=>input.onchange=async()=>{const file=input.files[0];input.value='';if(!file)return;const key=input.dataset.planReference;if(references[key].length>=8){toast('Use up to eight charts per group');return;}itemUploads++;WS.dialogBusy=true;$('#wsItemForm button[type=submit]').disabled=true;$('#wsItemStatus').textContent='Uploading chart…';try{const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file);});const response=await fetch('/api/upload',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({data})});const result=await response.json();if(!response.ok||!result.path)throw Error('Chart upload failed');references[key].push(result.path);WS.dialogDirty=true;renderReferences();$('#wsItemStatus').textContent='Chart attached. Save the plan to keep it.';}catch(error){$('#wsItemStatus').textContent=error.message;}finally{itemUploads--;WS.dialogBusy=itemUploads>0;$('#wsItemForm button[type=submit]').disabled=itemUploads>0;}});
const requestId=crypto.randomUUID();$('#wsItemForm').onsubmit=async event=>{event.preventDefault();if(itemUploads)return;const form=event.currentTarget,data=new FormData(form);let clean={};if(kind==='note')clean={content:data.get('content'),tags:data.get('tags'),pinned:data.has('pinned')};if(kind==='strategy')clean={...body,description:data.get('description'),active:data.has('active'),charting:wsLines(data.get('charting')),criteria:wsLines(data.get('criteria')),management:wsLines(data.get('management')),exitRules:data.get('exitRules'),notes:wsLines(data.get('notes')),setupImages:references.setupImages,entryImages:references.entryImages};if(kind==='event'){if(!data.get('at')){$('#wsItemStatus').textContent='Choose an event date and time.';return;}clean={at:new Date(data.get('at')).toISOString(),impact:data.get('impact'),currency:data.get('currency'),source:data.get('source'),notes:data.get('notes')};}if(kind==='resource')clean={url:data.get('url'),category:data.get('category'),notes:data.get('notes')};WS.dialogBusy=true;form.querySelectorAll('button,input,select,textarea').forEach(el=>el.disabled=true);$('#wsItemStatus').textContent='Saving…';try{await wsApi('items'+(item?'/'+item.id:''),item?'PUT':'POST',{kind,title:data.get('title'),body:clean,revision:item?.revision,clientId:requestId});await wsReload(kind);wsCloseDialog(true);renderWorkspaceView(view);toast('Saved');}catch(error){WS.dialogBusy=false;$('#wsItemStatus').textContent=error.message;form.querySelectorAll('button,input,select,textarea').forEach(el=>el.disabled=false);}};}
function renderStrategies(){const strategies=WS.items.strategy;$('#ws-strategies').innerHTML=wsHeader('YOUR EDGE, WRITTEN DOWN','Playbook','Turn your setup into clear rules. Keep the plan beside every trade.',`${wsBtn('Checklist defaults','plan-defaults',true)}${wsBtn('+ New trade plan','new-strategy')}`)+`<div class="ws-notice">Plans are recorded with each trade. Editing or deleting a library plan will leave saved trade snapshots intact.</div><div class="ws-cards">${Object.entries(PLAN_SETTINGS.templates).map(([key,template])=>`<article class="ws-card ws-item-card"><span class="ws-tag purple">Checklist preset</span><h2>${esc(template.name)}</h2><p class="ws-note-copy">${template.criteria.slice(0,3).map(esc).join('<br>')}</p><div class="ws-meta">${template.criteria.length} entry criteria · managed in Settings</div><div class="ws-actions">${wsBtn('Use preset','use-preset',false,`data-type="${key}"`)}${wsBtn('Edit defaults','plan-defaults',true)}</div></article>`).join('')}${strategies.map(item=>{const trades=allTrades.filter(t=>Number(t.strategy_id)===item.id),summary=wsSummary(trades);return `<article class="ws-card ws-item-card"><span class="ws-tag ${item.body.active?'green':''}">${item.body.active?'Active':'Archived'}</span><h2>${esc(item.title)}</h2><p class="ws-note-copy">${esc(item.body.description||item.body.criteria.join('\n'))}</p><div class="ws-stat-row"><span>Trades<b>${trades.length}</b></span><span>Net P&L<b class="${wsSign(summary.net)}">${money(summary.net)}</b></span><span>Criteria<b>${item.body.criteria.length}</b></span></div><div class="ws-actions">${wsBtn('Use for trade','use-strategy',false,`data-id="${item.id}" ${!item.body.active?'disabled':''}`)}${wsBtn('Edit plan','edit-item',true,`data-kind="strategy" data-id="${item.id}"`)}</div></article>`;}).join('')}</div>`;}
function renderNotebook(){const notes=[...WS.items.note].sort((a,b)=>Number(b.body.pinned)-Number(a.body.pinned)||b.id-a.id);$('#ws-notebook').innerHTML=wsHeader('AFTER · THINK ON PAPER','Notebook','Keep market observations, lessons and ideas in one place.',`${wsBtn('+ New note','new-note')}`)+`<div class="ws-filter"><label class="ws-field ws-search">Find a note<input id="wsNoteSearch" placeholder="Search titles, notes and tags"></label></div><div class="ws-cards" id="wsNoteCards">${notes.length?notes.map(item=>`<article class="ws-card ws-item-card" data-note-search="${esc((item.title+' '+item.body.content+' '+item.body.tags).toLowerCase())}"><div class="ws-actions"><span class="ws-tag ${item.body.pinned?'purple':''}">${item.body.pinned?'Pinned note':'Note'}</span><span class="ws-meta">${wsDate(item.updated_at)}</span></div><h2>${esc(item.title)}</h2><p class="ws-note-copy">${esc(item.body.content)}</p><div class="ws-meta">${esc(item.body.tags||'No tags')}</div><div class="ws-actions">${wsBtn('Open note','edit-item',true,`data-kind="note" data-id="${item.id}"`)}</div></article>`).join(''):wsEmpty('Make room for your thinking','Save a market observation, a chart lesson, or a rule you want to remember.','new-note','+ Write a note')}</div><p class="ws-inline-feedback" id="wsNoteCount">${notes.length} notes</p>`;$('#wsNoteSearch').oninput=event=>{const term=event.target.value.trim().toLowerCase();let count=0;$$('[data-note-search]').forEach(card=>{card.hidden=!card.dataset.noteSearch.includes(term);if(!card.hidden)count++;});$('#wsNoteCount').textContent=count+' matching notes';};}
function wsEventRow(item){const date=new Date(item.body.at);return `<div class="ws-calendar-event"><div class="ws-event-time"><b>${esc(date.toLocaleTimeString(undefined,{hour:'2-digit',minute:'2-digit'}))}</b><div class="sub">${esc(date.toLocaleDateString(undefined,{month:'short',day:'numeric'}))}</div></div><div class="ws-event-main"><h3>${esc(item.title)}</h3><div class="sub">${esc(item.body.currency||'Market event')} · <span class="ws-tag ${item.body.impact==='high'?'red':item.body.impact==='medium'?'purple':''}">${esc(item.body.impact)} impact</span></div></div><div class="ws-actions">${wsBtn('Edit','edit-item',true,`data-kind="event" data-id="${item.id}"`)}</div></div>`;}
function renderEvents(){const events=[...WS.items.event].sort((a,b)=>Date.parse(a.body.at)-Date.parse(b.body.at));$('#ws-events').innerHTML=wsHeader('BEFORE · CHECK NEWS AND EVENTS','Market calendar','Keep economic releases, earnings and other events in your trading plan.',`${wsBtn('+ Add event','new-event')}`)+`<div class="ws-notice">Personal event calendar · manually entered. Times display in ${esc(Intl.DateTimeFormat().resolvedOptions().timeZone)}. No live economic calendar feed is connected.</div><div class="ws-card">${events.length?events.map(item=>`<div>${wsEventRow(item)}${item.body.notes?`<p class="ws-note-copy">${esc(item.body.notes)}</p>`:''}${item.body.source?`<a class="ws-link" href="${esc(item.body.source)}" target="_blank" rel="noopener noreferrer">Open source ↗</a>`:''}</div>`).join(''):wsEmpty('A clear calendar is part of your preparation','Add an event with its source, impact and the markets it affects.','new-event','+ Add your first event')}</div>`;}
function renderResources(){const resources=WS.items.resource;$('#ws-resources').innerHTML=wsHeader('BUILD YOUR OWN KNOWLEDGE','Learning library','Collect the resources and lessons that support your trading process.',`${wsBtn('+ Add resource','new-resource')}`)+`<div class="ws-cards">${resources.length?resources.map(item=>`<article class="ws-card ws-item-card"><span class="ws-tag purple">${esc(item.body.category)}</span><h2>${esc(item.title)}</h2><p class="ws-note-copy">${esc(item.body.notes)}</p><div class="ws-actions">${item.body.url?`<a class="btn ghost ws-link" href="${esc(item.body.url)}" target="_blank" rel="noopener noreferrer">Open resource ↗</a>`:''}${wsBtn('Edit','edit-item',true,`data-kind="resource" data-id="${item.id}"`)}</div></article>`).join(''):wsEmpty('Your learning, in one place','Save a course, a useful article or your own research notes.','new-resource','+ Add a resource')}</div>`;}
function wsGuardStatus(){const limits=WS.guard.settings,capital=Number(WS.prefs.settings.capital),day=allTrades.filter(t=>t.date===wsLocalDate()),daily=wsSummary(day),all=wsSummary();const openRisk=all.open.reduce((sum,t)=>sum+(Number(t.risk)||0),0),missing=all.open.filter(t=>t.risk==null||t.risk==='').length;const flags=[];if(limits.enabled){if(capital<=0)flags.push('Set your starting balance to calculate money limits.');if(capital>0&&daily.net<=-capital*limits.dailyLoss/100)flags.push('Daily loss limit reached.');if(day.length>=limits.maxTrades)flags.push('Daily trade limit reached.');if(capital>0&&all.drawdownPct>=limits.maxDrawdown)flags.push('Current drawdown limit reached.');if(capital>0&&openRisk>=capital*limits.maxOpenRisk/100)flags.push('Open risk limit reached.');if(limits.requireRoutine&&routineState&&routineState.checked.length<routineState.settings.steps.length)flags.push('Pre-market routine is incomplete.');if(missing)flags.push(`${missing} open trade${missing===1?' has':'s have'} no recorded risk.`);}return{limits,capital,daily,day,all,openRisk,missing,flags};}
function renderGuardrails(){const state=wsGuardStatus(),{limits,capital,daily,day,all,openRisk}=state;$('#ws-guardrails').innerHTML=wsHeader('BEFORE · WITHIN YOUR RULES?','Guardrails','Define your journal limits before your next session.',`${wsBtn('Open risk planner','planner',true)}`)+`<div class="ws-notice">These guardrails check the trades recorded in this journal and show planning alerts. They do not block orders at your broker or monitor live positions.</div>${state.flags.length?`<div class="ws-notice warning">${state.flags.map(esc).join('<br>')}</div>`:''}<div class="ws-kpis">${wsKpi('Today’s net P&L',money(daily.net),capital>0?`Loss limit ${money(capital*limits.dailyLoss/100)}`:'Set starting balance',wsSign(daily.net))}${wsKpi('Trades today',String(day.length),`Daily limit: ${limits.maxTrades}`)}${wsKpi('Recorded open risk',money(openRisk),capital>0?`Limit ${money(capital*limits.maxOpenRisk/100)}`:'From open trade risk fields')}${wsKpi('Current drawdown',money(all.drawdown),`${wsNum(limits.maxDrawdown)}% configured limit`)}</div><div class="ws-grid"><section class="ws-card ws-span-7"><div class="ws-card-head"><h2>Your limits</h2><span class="ws-tag ${limits.enabled?'green':''}">${limits.enabled?'Enabled':'Disabled'}</span></div><form id="wsGuardForm"><div class="ws-form-grid"><label class="ws-check full"><input name="enabled" type="checkbox" ${limits.enabled?'checked':''}>Enable journal guardrail alerts</label>${wsField('Risk per trade (%)','riskPerTrade',limits.riskPerTrade,'number')}${wsField('Maximum daily loss (%)','dailyLoss',limits.dailyLoss,'number')}${wsField('Maximum drawdown (%)','maxDrawdown',limits.maxDrawdown,'number')}${wsField('Maximum trades per day','maxTrades',limits.maxTrades,'number')}${wsField('Maximum total open risk (%)','maxOpenRisk',limits.maxOpenRisk,'number')}<label class="ws-check"><input name="requireRoutine" type="checkbox" ${limits.requireRoutine?'checked':''}>Check pre-market completion</label><label class="ws-check full"><input name="requireChecklist" type="checkbox" ${limits.requireChecklist?'checked':''}>Check entry checklist completion</label></div><div class="ws-form-footer"><button class="btn" type="submit">Save limits</button><span id="wsGuardStatus" class="ws-form-status" role="status"></span></div></form></section><section class="ws-card ws-span-5"><h2>How limits are measured</h2><ul class="ws-list" style="margin-top:20px"><li><span class="ws-check-dot">1</span><div>One journal currency<span class="sub">${esc(WS.prefs.settings.currency)}. Set your starting balance in Settings.</span></div></li><li><span class="ws-check-dot">2</span><div>Daily P&L includes fees<span class="sub">The trading date on each record defines the day.</span></div></li><li><span class="ws-check-dot">3</span><div>Open risk is recorded risk<span class="sub">Add risk to every open trade so exposure is visible.</span></div></li><li><span class="ws-check-dot">4</span><div>History stays recordable<span class="sub">You can always record a completed trade, including a rule break.</span></div></li></ul><hr class="ws-divider">${wsBtn('Set journal balance','preferences',true)}</section></div>`;$$('#wsGuardForm input[type=number]').forEach(input=>{input.step=input.name==='maxTrades'?'1':'0.01';input.min=input.name==='maxTrades'?'1':'0.01';input.required=true;});$('#wsGuardForm').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget,values=new FormData(form),settings={};for(const key of ['enabled','requireRoutine','requireChecklist'])settings[key]=values.has(key);for(const key of ['riskPerTrade','dailyLoss','maxDrawdown','maxTrades','maxOpenRisk'])settings[key]=Number(values.get(key));await wsSaveSettingsForm('guardrails',settings,WS.guard,'wsGuardStatus',form,result=>{WS.guard=result;renderGuardrails();});};}
async function wsSaveSettingsForm(path,settings,current,statusId,form,onSuccess){const status=$('#'+statusId);form.querySelectorAll('input,button,select').forEach(el=>el.disabled=true);status.textContent='Saving…';try{const result=await wsApi(path,'PUT',{settings,revision:current.revision});onSuccess(result);status.textContent='Saved.';toast('Settings saved');}catch(error){status.textContent=error.message;}finally{form.querySelectorAll('input,button,select').forEach(el=>el.disabled=false);}}
function renderPlanner(){const capital=Number(WS.prefs.settings.capital);$('#ws-planner').innerHTML=wsHeader('BEFORE · PLAN THE TRADE','Planning','Define your entry, stop and target, then size the position to your risk budget.','<span class="ws-tag purple">Planning only · no orders placed</span>')+`<div class="ws-grid"><section class="ws-card ws-span-7"><div class="ws-card-head"><h2>Plan the position</h2><span class="ws-tag">${esc(WS.prefs.settings.currency)}</span></div><form id="wsPlannerForm"><div class="ws-form-grid">${wsField('Symbol','symbol','','text')}${wsSelect('Direction','direction',['Long','Short'],'Long')}${wsField('Account balance','capital',capital||'','number')}${wsField('Risk budget (%)','risk',WS.guard.settings.riskPerTrade,'number')}${wsField('Entry price','entry','','number')}${wsField('Stop price','stop','','number')}${wsField('Target price','target','','number')}${wsField('Quantity increment','step',1,'number')}${wsField('Contract multiplier','cv',1,'number')}</div><p class="ws-inline-feedback">For cash shares, use multiplier 1 and quantity increment 1. For contracts, use your broker’s contract value and lot increment. Estimated risk excludes slippage and fees.</p><div class="ws-form-footer"><button type="submit" class="btn">Calculate position</button></div></form></section><section class="ws-card ws-span-5"><div class="ws-card-head"><h2>Position estimate</h2><span class="ws-tag">Before costs</span></div><div id="wsPlannerResult">${wsEmpty('Define the trade first','Enter an entry, stop, target and balance to calculate the position size and planned reward.')}</div></section></div>`;$$('#wsPlannerForm input[type=number]').forEach(input=>{input.step='any';input.min='0';input.required=true;});$('#wsPlannerForm [name=symbol]').required=true;$('#wsPlannerForm').onsubmit=event=>{event.preventDefault();const f=Object.fromEntries(new FormData(event.currentTarget)),number=key=>Number(f[key]);const c=number('capital'),percent=number('risk'),entry=number('entry'),stop=number('stop'),target=number('target'),step=number('step'),cv=number('cv'),direction=f.direction==='Short'?-1:1;const result=$('#wsPlannerResult');if(![c,percent,entry,stop,target,step,cv].every(n=>Number.isFinite(n)&&n>0)||percent>100||(entry-stop)*direction<=0||(target-entry)*direction<=0){result.innerHTML='<div class="ws-notice warning">Use positive values, a stop on the loss side, and a target on the profit side. Risk must be at most 100%.</div>';return;}const budget=c*percent/100,perUnit=Math.abs(entry-stop)*cv,quantity=Math.floor((budget/perUnit)/step+1e-10)*step,risk=quantity*perUnit,reward=quantity*Math.abs(target-entry)*cv,rr=Math.abs(target-entry)/Math.abs(entry-stop);const guard=wsGuardStatus(),alerts=[...guard.flags];if(guard.limits.enabled&&percent>guard.limits.riskPerTrade)alerts.push('This risk percentage exceeds your per-trade limit.');if(guard.limits.enabled&&guard.capital>0&&guard.openRisk+risk>guard.capital*guard.limits.maxOpenRisk/100)alerts.push('This plan would exceed your recorded open-risk limit.');if(quantity<=0)alerts.push('Your risk budget does not cover one quantity increment.');WS.planner={...f,quantity,risk,reward,rr};result.innerHTML=`<div class="ws-kpi"><div class="ws-label">Estimated quantity</div><div class="ws-value">${wsNum(quantity,8)}</div><div class="ws-foot">Rounded down to ${wsNum(step,8)} increments</div></div>${[['Risk budget',money(budget)],['Risk at stop',money(risk)],['Reward at target',money(reward)],['Planned R:R',`1 : ${wsNum(rr,2)}`],['Notional exposure',money(quantity*entry*cv)]].map(([label,value])=>`<div class="ws-progress-row"><span>${label}</span><b class="num">${value}</b></div>`).join('')}${alerts.length?`<div class="ws-notice warning">${alerts.map(esc).join('<br>')}</div>`:''}${wsBtn('Use in journal draft','planner-draft',false,quantity<=0?'disabled':'')}<p class="ws-inline-feedback">This creates a journal draft. It does not send an order.</p>`;};}
function loadTradeReview(trade){const review=wsReview(trade||{});$('#f_strategy').innerHTML='<option value="">Use checklist defaults</option>'+WS.items.strategy.filter(item=>item.body.active||item.id===Number(trade?.strategy_id)).map(item=>`<option value="${item.id}">${esc(item.title)}</option>`).join('');if(trade?.strategy_id&&!WS.items.strategy.some(item=>item.id===Number(trade.strategy_id)))$('#f_strategy').insertAdjacentHTML('beforeend',`<option value="${Number(trade.strategy_id)}">Recorded plan (removed from library)</option>`);$('#f_strategy').value=trade?.strategy_id||'';$('#f_followed').value=review.followedPlan===true?'yes':review.followedPlan===false?'no':'';$('#f_quality').value=review.quality||'';$('#f_execution').value=review.execution||'';$('#f_emotion_in').value=review.emotionIn||'';$('#f_emotion_out').value=review.emotionOut||'';$('#f_management').value=review.management||'';$('#f_mistakes').value=review.mistakes||'';$('#f_reviewed').checked=review.reviewed===true;$('#f_entry_time').value=trade?.entry_time||'';$('#f_exit_time').value=trade?.exit_time||'';const guard=wsGuardStatus();$('#wsTradeGuardrails').textContent=guard.limits.enabled?['Journal guardrails',...guard.flags].join(' · '):'';}
function showTradeGuardrails(){const target=$('#wsTradeGuardrails');if(!target)return;const state=wsGuardStatus(),warnings=[...state.flags];
if(state.limits.enabled&&state.limits.requireChecklist&&!$('#f_plan_active').checked)warnings.push('Entry checklist is paused.');if(state.limits.enabled&&state.limits.requireChecklist&&$('#f_plan_active').checked&&tradeChecklistItems().some(item=>!tradeChecks.has(item)))warnings.push('Entry checklist is incomplete.');
target.textContent=state.limits.enabled?(warnings.length?warnings.join(' · '):'Journal guardrails: no recorded limit reached.') : '';}
function workspaceTradeFields(){return{strategy_id:$('#f_strategy').value?Number($('#f_strategy').value):null,entry_time:$('#f_entry_time').value||null,exit_time:$('#f_exit_time').value||null,contract_value:importCV,review:JSON.stringify({version:1,followedPlan:$('#f_followed').value==='yes'?true:$('#f_followed').value==='no'?false:null,quality:$('#f_quality').value,execution:$('#f_execution').value,emotionIn:$('#f_emotion_in').value,emotionOut:$('#f_emotion_out').value,management:$('#f_management').value.trim(),mistakes:$('#f_mistakes').value.trim(),reviewed:$('#f_reviewed').checked,reviewedAt:$('#f_reviewed').checked?new Date().toISOString():null})};}
function wsApplyStrategy(item){$('#f_strategy').value=item.id;$('#f_plan_type').value='custom';formTemplate={...clonePlan(item.body),name:item.title};$('#f_exit_rules').value=formTemplate.exitRules;tradeChecks=new Set();renderPlanTemplate();}
$('#f_strategy').onchange=()=>{const item=WS.items.strategy.find(item=>item.id===Number($('#f_strategy').value));if(item)wsApplyStrategy(item);};
function wsReviewFields(review){return wsSelect('Did you follow your plan?','followed',[['','Not reviewed'],['yes','Yes'],['no','No']],review.followedPlan===true?'yes':review.followedPlan===false?'no':'')+wsSelect('Setup quality','quality',[['','Not rated'],'A+','A','B','C','F'],review.quality||'')+wsSelect('Execution quality','execution',[['','Not rated'],'Excellent','Good','Average','Poor'],review.execution||'')+wsSelect('Entry emotion','emotionIn',[['','Not recorded'],'Calm','Confident','Anxious','FOMO','Frustrated','Tired'],review.emotionIn||'')+wsSelect('Exit emotion','emotionOut',[['','Not recorded'],'Satisfied','Calm','Relieved','Frustrated','Regretful'],review.emotionOut||'')+wsTextField('Trade management','management',review.management||'')+wsTextField('Mistakes and the next action','mistakes',review.mistakes||'');}
function wsTradeDetail(id){const trade=allTrades.find(t=>t.id===Number(id));if(!trade){toast('This trade no longer exists');return;}const review=wsReview(trade),plan=wsJson(trade.plan),paths=wsJson(trade.images,[]),safePaths=Array.isArray(paths)?paths.filter(path=>typeof path==='string'&&/^images\/[a-zA-Z0-9_.-]+\.(png|jpg|jpeg|webp|gif)$/.test(path)):[];const facts=[['Date',trade.date||'—'],['Direction',trade.direction||'—'],['Quantity',fmt(trade.qty)],['Entry price',fmt(trade.entry)],['Stop price',fmt(trade.stop)],['Exit price',fmt(trade.exit)],['Recorded risk',money(trade.risk)],['Return',trade.r_multiple==null?'—':fmt(trade.r_multiple)+'R'],['Gross P&L',money(trade.pnl)],['Fees',money(Number(trade.fee)||0)],['Net P&L',wsClosed(trade)?money(wsNet(trade)):'Open'],['Trade plan',plan.template?.name||trade.setup||'—']];if(!wsShowDialog(`${esc(trade.symbol||'Trade')} · review`,'Review the decision, execution and result.',`<div class="ws-review-grid"><aside class="ws-trade-facts"><div class="ws-eyebrow">NET P&L</div><div class="ws-value ${wsClosed(trade)?wsSign(wsNet(trade)):''}">${wsClosed(trade)?money(wsNet(trade)):'Open trade'}</div><span class="ws-tag ${wsReviewed(trade)?'green':'amber'}">${wsReviewed(trade)?'Reviewed':'Awaiting review'}</span><hr class="ws-divider">${facts.map(([label,value])=>`<div class="ws-fact"><span>${label}</span><b>${esc(value)}</b></div>`).join('')}<hr class="ws-divider">${wsBtn('Edit trade details','edit-trade',true,`data-id="${trade.id}"`)}</aside><div><h3>Recorded charts</h3><div class="ws-trade-gallery">${safePaths.length?safePaths.map((path,i)=>`<a href="/${esc(path)}" target="_blank" rel="noopener noreferrer"><img src="/${esc(path)}" alt="Recorded trade chart ${i+1}"></a>`).join(''):wsEmpty('No trade screenshots','Add your chart screenshots in Edit trade details. This view shows your uploaded charts. It does not generate a market replay.')}</div><div class="ws-card-head"><h2>Review & reflection</h2><span class="ws-tag purple">Your execution</span></div><form id="wsReviewForm"><div class="ws-form-grid">${wsReviewFields(review)}${wsTextField('Notes and lessons','notes',trade.notes||'')}<label class="ws-check full"><input name="reviewed" type="checkbox" ${review.reviewed?'checked':''}>Mark as reviewed</label></div><div class="ws-form-footer"><span id="wsReviewStatus" class="ws-form-status" role="status"></span><button class="btn" type="submit">Save review</button></div></form></div></div>`,true))return;$('#wsReviewForm').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget,data=new FormData(form),clean={version:1,followedPlan:data.get('followed')==='yes'?true:data.get('followed')==='no'?false:null,quality:data.get('quality'),execution:data.get('execution'),emotionIn:data.get('emotionIn'),emotionOut:data.get('emotionOut'),management:data.get('management'),mistakes:data.get('mistakes'),reviewed:data.has('reviewed'),reviewedAt:data.has('reviewed')?new Date().toISOString():null};WS.dialogBusy=true;form.querySelectorAll('input,select,textarea,button').forEach(input=>input.disabled=true);$('#wsReviewStatus').textContent='Saving…';try{await wsApi('review/'+trade.id,'PUT',{review:clean,notes:data.get('notes'),expectedReview:trade.review||null,expectedNotes:trade.notes||null});await loadAll();if(selectedDate)await selectDay(selectedDate);wsCloseDialog(true);renderWorkspaceView(view);toast('Review saved');}catch(error){WS.dialogBusy=false;$('#wsReviewStatus').textContent=error.message;form.querySelectorAll('input,select,textarea,button').forEach(input=>input.disabled=false);}};}
function renderDayReflection(){const target=$('#wsDayReflection');if(!target||!dayData)return;const date=selectedDate,log=WS.dayDrafts[date]||dayData.log||{};const sections=[['market','Market context & bias'],['watchlist','Watchlist & levels'],['mistakes','What can I improve?'],['did_great','What went well?'],['reinforcement','One action for next time'],['overall','Session reflection']];target.innerHTML=`<section class="ws-day-reflection"><h3>Daily preparation & reflection</h3><p class="ws-subtitle">Your session notes for ${esc(date)}.</p><form id="wsDayForm"><div class="ws-form-grid">${sections.map(([key,label])=>wsTextField(label,key,log[key]||'',false)).join('')}${wsField('Day tags','tags',log.tags||'','text',true)}</div><div class="ws-form-footer"><button type="submit" class="btn">Save day notes</button><span class="ws-form-status" id="wsDayStatus" role="status"></span></div></form></section>`;$('#wsDayForm').oninput=event=>{WS.dayDrafts[date]={...log,...Object.fromEntries(new FormData(event.currentTarget))};};$('#wsDayForm').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget,body={...log,...Object.fromEntries(new FormData(form)),date};form.querySelector('button').disabled=true;$('#wsDayStatus').textContent='Saving…';try{const response=await fetch('/api/daylog',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});if(!response.ok)throw Error('Could not save day notes');if(selectedDate===date)dayData.log=body;delete WS.dayDrafts[date];form.querySelector('[role=status]').textContent='Saved.';loadDays(false);}catch(error){form.querySelector('[role=status]').textContent=error.message;}finally{form.querySelector('button').disabled=false;}};}
function wsFocusRemaining(){if(!WS.focus)return 15*60;return WS.focus.running?Math.max(0,Math.ceil((WS.focus.deadline-Date.now())/1000)):WS.focus.remaining;}
function wsPersistFocus(){try{localStorage.setItem('tj_focus_session',JSON.stringify(WS.focus));}catch{}}
function wsFocusTick(){if(!WS.focus)return;const remaining=wsFocusRemaining();if(WS.focus.running&&remaining===0){WS.focus.running=false;WS.focus.remaining=0;WS.focus.completed=true;wsPersistFocus();if(view==='focus')renderFocus();toast('Focus session complete');}const clock=$('#wsFocusClock');if(clock)clock.textContent=`${String(Math.floor(remaining/60)).padStart(2,'0')}:${String(remaining%60).padStart(2,'0')}`;}
function renderFocus(){if(!WS.focus){try{const saved=JSON.parse(localStorage.getItem('tj_focus_session'));if(saved&&Number.isFinite(saved.duration)&&saved.duration>=1&&saved.duration<=120&&Number.isFinite(saved.remaining)&&saved.remaining>=0&&Number.isFinite(saved.deadline))WS.focus=saved;}catch{}}const focus=WS.focus,remaining=wsFocusRemaining();$('#ws-focus').innerHTML=wsHeader('','Meditation','A little space between the impulse and the decision. Set a timer, breathe, then write one intention.','<span class="ws-tag purple">Private · no audio required</span>')+`<div class="ws-grid"><section class="ws-card ws-span-7 ws-focus ${focus?.running?'active':''}"><div class="ws-focus-orb">${focus?.running?'Breathe slowly':'Take a breath'}</div><div class="ws-focus-clock" id="wsFocusClock">${String(Math.floor(remaining/60)).padStart(2,'0')}:${String(remaining%60).padStart(2,'0')}</div>${!focus||focus.completed?`<label class="ws-field">Session length<select id="wsFocusDuration">${[2,5,10,15,20,30].map(n=>`<option value="${n}" ${n===(focus?.duration||15)?'selected':''}>${n} minutes</option>`).join('')}</select></label>`:''}<div class="ws-actions" style="margin-top:22px">${focus?.running?wsBtn('Pause','focus-pause'):wsBtn(focus&&!focus.completed?'Continue':'Start session','focus-start')}${focus&&!focus.completed?wsBtn('Reset','focus-reset',true):''}</div><p class="ws-subtitle" style="margin:18px auto 0">${focus?.completed?'Session complete. Record one clear intention for your next trade.':'Relax your shoulders. Breathe naturally. Bring your attention back to the plan.'}</p>${focus?.completed&&!focus.saved?`<form id="wsFocusReflection" style="text-align:left;margin-top:24px">${wsTextField('One sentence to carry into your session','reflection')}<div class="ws-form-footer"><button class="btn" type="submit">Save session</button><span id="wsFocusStatus" class="ws-form-status"></span></div></form>`:''}${focus?.saved?'<p class="ws-inline-feedback">Session saved to your focus history.</p>':''}</section><section class="ws-card ws-span-5"><div class="ws-card-head"><h2>Recent sessions</h2><span class="ws-tag">${WS.items.session.length} completed</span></div>${WS.items.session.length?WS.items.session.slice(0,8).map(item=>`<div class="ws-insight"><span class="ws-insight-icon">✓</span><div><b>${wsNum(item.body.duration,0)}-minute focus session</b><p>${esc(item.body.reflection||'Time to reset and return to your process.')}</p><span class="ws-date">${wsDate(item.created_at)}</span></div></div>`).join(''):wsEmpty('Start a quieter session','Completed focus sessions and your reflections will appear here.')}</section></div>`;if($('#wsFocusReflection'))$('#wsFocusReflection').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget,reflection=new FormData(form).get('reflection');form.querySelector('button').disabled=true;try{await wsApi('items','POST',{kind:'session',title:'Focus session',clientId:focus.clientId,body:{duration:focus.duration,reflection,completed:true}});focus.saved=true;wsPersistFocus();await wsReload('session');renderFocus();}catch(error){$('#wsFocusStatus').textContent=error.message;form.querySelector('button').disabled=false;}};if(!WS.focusTimer)WS.focusTimer=setInterval(wsFocusTick,1000);}
const wsCSVColumns=['date','symbol','direction','setup','entry','stop','exit','qty','pnl','fee','risk','r_multiple','notes','tags','contract_value'];
function wsDownload(name,content,type){const url=URL.createObjectURL(new Blob([content],{type})),link=document.createElement('a');link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function wsExport(all=false){const rows=all===true?allTrades:wsFiltered();const safe=value=>{const raw=String(value??'');return '"'+(typeof value==='string'&&/^[=+@\-\t\r]/.test(raw)?"'"+raw:raw).replace(/"/g,'""')+'"';};wsDownload('trade-journal-'+wsLocalDate()+'.csv',[wsCSVColumns.join(','),...rows.map(row=>wsCSVColumns.map(key=>safe(row[key])).join(','))].join('\r\n'),'text/csv;charset=utf-8');toast('Exported '+rows.length+' trades');}
function wsParseCSV(text){text=text.replace(/^\uFEFF/,'');const rows=[];let row=[],value='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(quoted){if(c==='"'&&text[i+1]==='"'){value+='"';i++;}else if(c==='"')quoted=false;else value+=c;}else if(c==='"'&&value==='')quoted=true;else if(c===','){row.push(value);value='';}else if(c==='\n'||c==='\r'){if(c==='\r'&&text[i+1]==='\n')i++;row.push(value);if(row.some(cell=>cell.trim()))rows.push(row);row=[];value='';}else value+=c;}if(quoted)throw Error('CSV has an unclosed quote.');row.push(value);if(row.some(cell=>cell.trim()))rows.push(row);if(rows.length<2)throw Error('Add a header row and at least one trade.');const header=rows.shift().map(value=>value.trim().toLowerCase());if(new Set(header).size!==header.length)throw Error('CSV has duplicate headers.');if(!['date','symbol','direction'].every(key=>header.includes(key)))throw Error('CSV needs date, symbol and direction headers.');if(rows.length>1000)throw Error('Import up to 1,000 trades at a time.');return rows.map((row,index)=>{if(row.length!==header.length)throw Error('Column count differs on data row '+(index+1));return Object.fromEntries(header.map((key,i)=>[key,row[i].trim()]));});}
function wsOpenImport(){if(!wsShowDialog('Import trades from CSV','Preview first. Import adds records; identical CSV rows are skipped.',`<div class="ws-notice">Amounts must use this journal’s ${esc(WS.prefs.settings.currency)} currency. Required columns: date, symbol, direction. Use YYYY-MM-DD and Long / Short. P&L is gross; fees are separate.</div><label class="ws-field">Choose a CSV file<input type="file" id="wsImportFile" accept=".csv,text/csv"></label><button type="button" class="ws-link" data-ws-action="csv-template" style="margin-top:12px">Download column template</button><div id="wsImportPreview"></div><div class="ws-form-footer"><span id="wsImportStatus" class="ws-form-status" role="status"></span><button class="btn" type="button" id="wsImportConfirm" disabled>Import trades</button></div>`,true))return;let rows=[];$('#wsImportFile').onchange=async event=>{rows=[];$('#wsImportConfirm').disabled=true;$('#wsImportPreview').innerHTML='';const file=event.target.files[0];if(!file)return;if(file.size>5*1024*1024){$('#wsImportStatus').textContent='Use a CSV smaller than 5 MB.';return;}try{rows=wsParseCSV(await file.text());$('#wsImportStatus').textContent=rows.length+' trades ready for validation and import.';$('#wsImportPreview').innerHTML=`<p class="ws-subtitle">Preview · first ${Math.min(rows.length,8)} rows</p><div class="ws-table-wrap" style="margin-top:14px"><table class="ws-table"><thead><tr>${['Date','Symbol','Direction','P&L','Fees'].map(label=>`<th>${label}</th>`).join('')}</tr></thead><tbody>${rows.slice(0,8).map(row=>`<tr>${['date','symbol','direction','pnl','fee'].map(key=>`<td>${esc(row[key]||'—')}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;$('#wsImportConfirm').disabled=false;}catch(error){$('#wsImportStatus').textContent=error.message;}};$('#wsImportConfirm').onclick=async()=>{if(!rows.length)return;WS.dialogBusy=true;$('#wsImportConfirm').disabled=true;$('#wsImportFile').disabled=true;$('#wsImportStatus').textContent='Importing…';try{const result=await wsApi('import','POST',{rows});await loadAll();await loadDays(false);$('#wsImportStatus').textContent=`Imported ${result.imported}. Skipped ${result.skipped} identical rows.`;rows=[];WS.dialogDirty=false;renderWorkspaceView(view);}catch(error){$('#wsImportStatus').textContent=error.message;$('#wsImportConfirm').disabled=false;}finally{WS.dialogBusy=false;$('#wsImportFile').disabled=false;}};}
const WS_CURRENCIES=['USD','INR','EUR','GBP','AUD','CAD','SGD','AED','CHF','HKD','JPY','CNY','USDT'];
function wsCurrencyLabel(c){let name='';try{name=new Intl.DisplayNames(undefined,{type:'currency'}).of(c);}catch{}return c==='USDT'?'USDT · Tether (= USD)':`${c} · ${name||c}`;}
function wsFxNote(){const p=WS.prefs.settings,d=wsDisplayCurrency();if(d===p.currency)return `Showing amounts in ${esc(p.currency)}, the currency your trades are stored in.`;return `1 ${esc(p.currency)} = ${wsNum(Number(p.fxRate),4)} ${esc(d)}${p.fxAt?` · rate from ${esc(new Date(p.fxAt).toLocaleString(undefined,{dateStyle:'medium',timeStyle:'short'}))}`:''}. Updates automatically every 12 hours.`;}
async function wsFetchFx(display){const base=WS.prefs.settings.currency;if(display===base)return{rate:1};const response=await fetch(`/api/fx?base=${encodeURIComponent(base)}&to=${encodeURIComponent(display)}`);const r=await response.json();if(!response.ok||!(r.rate>0))throw Error('Could not get the exchange rate. Check your internet connection.');return r;}
// Re-render whatever is on screen so every amount picks up the new currency.
function wsAfterCurrencyChange(){const note=$('#wsFxNote');if(note)note.innerHTML=wsFxNote();loadDays(false);if(dayData)renderRail();if(view!=='settings')renderWorkspaceView(view);}
// Keep the saved rate fresh: refresh silently when it is older than 12 hours.
async function wsRefreshFx(){const p=WS.prefs.settings,d=wsDisplayCurrency();if(d===p.currency||(p.fxAt&&Date.now()-Date.parse(p.fxAt)<12*3600e3))return;try{const fx=await wsFetchFx(d);WS.prefs=await wsApi('preferences','PUT',{settings:{...p,fxRate:fx.rate,fxAt:new Date().toISOString()},revision:WS.prefs.revision});wsAfterCurrencyChange();}catch{}}
function renderWorkspaceSettings(){const panels=$('#pane-settings .settings-card');if(!$('#wsJournalPrefs')){const node=document.createElement('div');node.className='set-sec settings-panel';node.dataset.settingsPanel='journal';node.setAttribute('role','tabpanel');node.hidden=true;node.innerHTML='<div id="wsJournalPrefs"></div>';panels.append(node);const tab=document.createElement('button');tab.type='button';tab.role='tab';tab.id='settings-tab-journal';tab.dataset.settingsTab='journal';tab.setAttribute('aria-controls','settings-panel-journal');tab.textContent='Journal';tab.onclick=()=>showSettingsTab('journal');$('#pane-settings .settings-tabs').append(tab);}const prefs=WS.prefs.settings;if(!$('#wsPrefsForm')){$('#wsJournalPrefs').innerHTML=`<div class="set-label">Journal preferences</div><p class="plan-settings-help muted">Trades are stored in ${esc(prefs.currency)}. Pick a display currency and every amount in the app converts at the live exchange rate.</p><form id="wsPrefsForm"><div class="ws-form-grid">${wsField('Journal name','name',prefs.name,'text',true)}${wsSelect('Display currency','displayCurrency',WS_CURRENCIES.map(c=>[c,wsCurrencyLabel(c)]),wsDisplayCurrency())}<p class="ws-inline-feedback full" id="wsFxNote">${wsFxNote()}</p></div><div class="ws-form-footer"><button class="btn" type="submit">Save journal preferences</button><span class="ws-form-status" id="wsPrefsStatus" role="status"></span></div></form><hr class="ws-divider"><h3>Back up your journal</h3><p class="plan-settings-help muted">Download the database, plans, notes, routines and uploaded charts. Broker credentials and login sessions are excluded.</p>${wsBtn('Download full backup (.zip)','backup',true)}`;$('#wsPrefsForm').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget,data=new FormData(form);const display=data.get('displayCurrency');let fx;try{fx=await wsFetchFx(display);}catch(error){$('#wsPrefsStatus').textContent=error.message;return;}await wsSaveSettingsForm('preferences',{...WS.prefs.settings,name:data.get('name'),displayCurrency:display,fxRate:fx.rate,fxAt:new Date().toISOString()},WS.prefs,'wsPrefsStatus',form,result=>{WS.prefs=result;wsAfterCurrencyChange();});};}
if(!$('#wsBackupData')){const dataPanel=$('[data-settings-panel=data]');dataPanel.insertAdjacentHTML('beforeend',`<div id="wsBackupData"><hr class="ws-divider"><div class="set-row"><span>Complete journal backup · database and charts</span>${wsBtn('Download backup','backup',true)}</div><div class="set-row" style="margin-top:14px"><span>Add trades from a CSV file</span>${wsBtn('Import CSV','import',true)}</div></div>`);}$('#setExport').onclick=()=>wsExport(true);}
window.renderWorkspaceView=function(key){if(key==='dashboard')renderDashboard();else if(key==='trades')renderTradeHistory();else if(key==='strategies')renderStrategies();else if(key==='planner')renderPlanner();else if(key==='guardrails')renderGuardrails();else if(key==='notebook')renderNotebook();else if(key==='events')renderEvents();else if(key==='focus')renderFocus();else if(key==='resources')renderResources();else if(key==='settings')renderWorkspaceSettings();};
async function wsNewTrade(){if(formVisible()&&$('#f_symbol').value&&!confirm('Open a new trade and discard the current editor?'))return false;setView('journal');await $('#addTradeBtn').onclick();return true;}
