 'new-trade':()=>wsNewTrade(),dashboard:()=>setView('dashboard'),trades:()=>setView('trades'),strategies:()=>setView('strategies'),planner:()=>setView('planner'),events:()=>setView('events'),
 routine:()=>$('#routineOpen').click(),preferences:()=>{setView('settings');showSettingsTab('journal');},'plan-defaults':()=>{settingsTab='playbook';if(typeof PB!=='undefined')PB.tab='presets';setView('edge');},pending:()=>{if(!wsSummary().pending.length){setView('journal');return;}WS.filters={from:'',to:'',symbol:'',direction:'',review:'pending'};WS.page=1;setView('trades');},
 'clear-filters':()=>{WS.filters={from:'',to:'',symbol:'',direction:'',review:''};WS.page=1;renderWorkspaceView(view);},'prev-page':()=>{WS.page--;renderTradeHistory();},'next-page':()=>{WS.page++;renderTradeHistory();},
 'new-note':()=>wsOpenItemEditor('note'),'new-strategy':()=>wsOpenItemEditor('strategy'),'new-event':()=>wsOpenItemEditor('event'),'new-resource':()=>wsOpenItemEditor('resource'),
 'edit-item':button=>wsOpenItemEditor(button.dataset.kind,WS.items[button.dataset.kind].find(item=>item.id===Number(button.dataset.id))),
 'delete-item':async button=>{const item=WS.items[button.dataset.kind].find(item=>item.id===Number(button.dataset.id));if(!item||!confirm('Delete "'+item.title+'"?'))return;button.disabled=true;try{await wsApi('items/'+item.id,'DELETE',{revision:item.revision});await wsReload(item.kind);wsCloseDialog(true);renderWorkspaceView(view);toast('Deleted');}catch(error){button.disabled=false;const status=$('#wsItemStatus');if(status)status.textContent=error.message;else toast(error.message);}},
 'close-dialog':()=>wsCloseDialog(),'trade-detail':button=>wsTradeDetail(button.dataset.id),'edit-trade':async button=>{if(WS.dialogDirty&&!confirm('Discard the unsaved review and open trade details?'))return;wsCloseDialog(true);await editTrade(Number(button.dataset.id));},
 'use-strategy':async button=>{const item=WS.items.strategy.find(item=>item.id===Number(button.dataset.id));if(item&&await wsNewTrade())wsApplyStrategy(item);},
 'use-preset':async button=>{if(!await wsNewTrade())return;$('#f_plan_type').value=button.dataset.type;$('#f_plan_type').dispatchEvent(new Event('change'));},
 'planner-draft':async()=>{const plan=WS.planner;if(!plan||!await wsNewTrade())return;$('#f_symbol').value=plan.symbol;$('#f_entry').value=plan.entry;$('#f_stop').value=plan.stop;$('#f_qty').value=plan.quantity;$('#f_risk').value=plan.risk;dir=plan.direction;importCV=Number(plan.cv);$('#f_logic').value=`Planned target: ${plan.target}. Planned R:R 1:${wsNum(plan.rr,2)}. Estimated reward before costs: ${money(plan.reward)}.`;syncSeg();calc();toast('Journal draft created. No order was placed.');},
 export:wsExport,import:wsOpenImport,'csv-template':()=>wsDownload('trade-journal-template.csv',wsCSVColumns.join(',')+'\r\n','text/csv;charset=utf-8'),
