 reload:async()=>{await loadWorkspace();renderWorkspaceView(view);},
 'focus-start':()=>{if(!WS.focus||WS.focus.completed){const duration=Number($('#wsFocusDuration')?.value)||15;WS.focus={duration,remaining:duration*60,running:true,deadline:Date.now()+duration*60000,completed:false,saved:false,clientId:crypto.randomUUID()};}else{WS.focus.running=true;WS.focus.deadline=Date.now()+WS.focus.remaining*1000;}wsPersistFocus();renderFocus();},
