document.addEventListener('click',event=>{const button=event.target.closest('[data-ws-action]');if(button){event.preventDefault();const action=wsActions[button.dataset.wsAction];if(action)Promise.resolve(action(button)).catch(error=>toast(error.message));return;}const row=event.target.closest('[data-ws-trade]');if(row)wsTradeDetail(row.dataset.wsTrade);});
document.addEventListener('keydown',event=>{const row=event.target.closest('[data-ws-trade]');if(row&&event.target===row&&['Enter',' '].includes(event.key)){event.preventDefault();wsTradeDetail(row.dataset.wsTrade);}});
$$('.navitem[data-view]').forEach(item=>item.onkeydown=event=>{if(['Enter',' '].includes(event.key)){event.preventDefault();item.click();}});
